6790\uff1b\u4e24\u81c2\u9884\u6ce8\u518c\uff0c\u4e0d\u5f97\u4e8b\u540e\u62e9\u4e00 |\n| \u6b21 | S1 | C1b,C1c\uff08\u66ff\u6362 C1\uff09 | 3 | 0 | 1 | \u6307\u4ee4\u6392\u540d\u654f\u611f\u6027 |\n| \u6b21 | S2 | C1,C2,C3 | 3 | 0.7 | 5 | \u91c7\u6837\u65b9\u5dee |\n| \u6b21 | S3 | C1,C2,C3 | 0 | 0 | 1 | \u7eaf zero-shot \u654f\u611f\u6027 |\n| \u6b21 | S4 | C3'\uff08\u5b57\u9762\u7a7a\u63d0\u793a\uff09 | 3 | 0 | 1 | \u57fa\u7ebf\u4fdd\u771f\u5ea6\u7b2c\u4e8c\u81c2\uff08\u4e0e P0 \u9884\u5148\u5e76\u5217\u6ce8\u518c\uff09 |\n| \u63a2 | E1 | C1,C2,C3 \u00d7 2 \u4e2a\u989d\u5916\u7f6e\u6362 | 3 | 0 | 1 | \u793a\u4f8b\u6392\u5217\u65b9\u5dee |\n| \u63a2 | E2 | C4 | 3 | 0 | 1 | \u6307\u4ee4\u957f\u5ea6\u914d\u5e73 |\n\n\u4e3b\u5206\u6790\u7f6e\u6362\u63a7\u5236\uff1a\u6bcf\u4efb\u52a1\u4f7f\u7528\u5355\u4e00\u7f6e\u6362\uff0c23\uff08\u5f85\u6838\uff09\u4e2a\u4efb\u52a1\u95f4\u6309\u62c9\u4e01\u65b9\u914d\u5e73\u4e09\u79cd\u793a\u4f8b\u7f6e\u6362\u3010\u59d4\u6258\u65b9\u88c1\u5b9a\u7684\u8bbe\u8ba1\u53c2\u6570\u3011\u3002\n\n## 3. \u4efb\u52a1\u4e0e\u6837\u672c\n3.1 \u4e3b\u5206\u6790\u8986\u76d6 BBH \u5168\u90e8\u5b50\u4efb\u52a1\uff0c\u5b98\u65b9\u53e3\u5f84\u3010\u59d4\u6258\u65b9\u88c1\u5b9a\u4e8c.1\u3011\u3002\u5b50\u4efb\u52a1\u603b\u6570\u5148\u9a8c\u4e3a 23\u3010\u5916\u90e8\u5148\u9a8c\u00b7\u672a\u9a8c\u8bc1\uff0c\u5f85\u6838\u5b57\u6bb5\u3011\uff1a**\u5b9a\u7a3f\u524d\u987b\u9010\u9879\u5217\u51fa\u5b9e\u9645\u7eb3\u5165\u6e05\u5355\u5e76\u8ba1\u6570\uff0c\u4ee5\u5217\u8868\u81ea\u8bc1**\uff0c\u6a21\u677f\u89c1\u9644\u5f55 D\uff0823 \u884c\u5168\u540d\u6e05\u5355\uff0c\u542b\u9010\u9879\u6838\u5bf9\u72b6\u6001\u5217\uff09\u3002\n3.2 \u6bcf\u4efb\u52a1\u6837\u672c\uff1aN=min(\u8be5\u4efb\u52a1\u5168\u91cf, N_design)\u3002N_design=125\u3010\u59d4\u6258\u65b9\u88c1\u5b9a\u7684\u8bbe\u8ba1\u53c2\u6570\u00b7\u540d\u4e49\u9ed8\u8ba4\u3011\u3002\u6837\u672c ID \u6e05\u5355\u5728\u4efb\u4f55\u8fd0\u884c\u524d\u51bb\u7ed3\u5e76\u5b58\u6863 SHA-256\u3002\n3.3 \u51bb\u7e