c47\u603b\u6570\u5b57\u3002\n- \u3010\u5047\u8bbe\u63a8\u6f14\u3011\uff1a\u4ee5\"\u5047\u8bbe\u8f93\u5165 \u2192 \u516c\u5f0f \u2192 \u8f93\u51fa\u533a\u95f4\"\u5f62\u5f0f\u5448\u73b0\u7684\u6570\u503c\uff0c\u4ec5\u4e3a\u53c2\u6570\u5316\u63a8\u6f14\uff0c\u975e\u5b9e\u6d4b\u3002\n\n---\n\n## 1. \u7814\u7a76\u95ee\u9898\u4e0e\u8868\u8ff0\u8fb9\u754c\n1.1 \u4e3b\u7814\u7a76\u95ee\u9898\uff1a\u5728\u56fa\u5b9a\u6a21\u578b\u3001\u56fa\u5b9a\u793a\u4f8b\u3001\u56fa\u5b9a\u89e3\u7801\u4e0e\u56fa\u5b9a\u8bc4\u5206\u5668\u4e0b\uff0c\u6307\u4ee4\u6587\u672c C1\uff08OPRO \u6240\u8f7d\u5355\u4e00\u6700\u4f73\u6307\u4ee4\uff09\u76f8\u5bf9 C2\uff08\"Let's think step by step.\"\uff09\u4e0e C3\uff08\u7a7a\u63d0\u793a\uff09\u5728 BBH \u4e0a\u7684\u51c6\u786e\u7387\u6548\u5e94\u3002\n1.2 \u8868\u8ff0\u8fb9\u754c\uff08\u88c1\u5b9a\u4e00.3\uff09\uff1a\u56e0 C1 \u7684\u51fa\u5904\u5f52\u5c5e\uff08GSM8K \u4f18\u5316\u4ea7\u7269 vs BBH \u4f18\u5316\u4ea7\u7269\uff09\u5728\u672c\u4ed3\u5e93\u4e0d\u53ef\u786e\u8bc1\uff0c\u4e3b\u7ed3\u8bba\u53ea\u5141\u8bb8\u8868\u8ff0\u4e3a**\"\u8be5\u6307\u4ee4\u6587\u672c\u5728 BBH \u4e0a\u662f\u5426\u76f8\u5bf9\u4e24\u4e2a\u57fa\u7ebf\u66f4\u4f18\"**\uff1b\"\u8de8\u4efb\u52a1\u8fc1\u79fb\u6709\u6548\"\u662f\u5f85\u68c0\u9a8c\u5047\u8bbe\uff0c\u4e0d\u5f97\u8868\u8ff0\u4e3a\"OPRO \u5728 BBH \u4e0a\u627e\u5230\u7684\u6307\u4ee4\u66f4\u4f18\"\u8fd9\u4e00\u65e2\u6709\u4e8b\u5b9e\u3002\n1.3 \u6a21\u578b\u5916\u63a8\u9650\u5236\uff08\u88c1\u5b9a\u4e00.1\uff09\uff1aOPRO \u539f\u6587\u6267\u884c\u5668\u5728\u672c\u73af\u5883\u4e0d\u53ef\u8fbe\u3001\u4e0d\u53ef\u590d\u73b0\u3010\u4ed3\u5e93\u5b9e\u6d4b\uff1a\u65e0\u7f51\u7edc/\u65e0\u51ed\u636e/\u65e0 GPU\u3011\u3002\u672c\u8bbe\u8ba1\u68c0\u9a8c\u7684\u662f**\u6307\u4ee4\u8de8\u6a21\u578b\u8fc1\u79fb\u540e\u7684\u76f8\u5bf9\u6548\u5e94**\uff0c\u8bc4\u6d4b\u5bf9\u8c61\u4e3a\u5355\u4e00\u6307\u4ee4\u7c7b API \u6a21\u578b + \u9489\u6b7b\u5feb\u7167\u7248\u672c\u53f7\u3010\u59d4\u6258\u65b9\u88c1\u5b9a\u7684\u8bbe\u8ba1\u53c2\u6570\uff1b\u5feb\u7167\u5b57\u7b26\u4e32\u8fd0\u884c\u65f6\u586b\u5199\uff0c\u5c5e\u5f85\u6838\u5b57\u6bb5\u3011\u3002\n\n## 2. \u6761\u4ef6\u4e0e\u81c2\u603b\u8868\n\u6761\u4ef6\u5e93\uff1a\n- C1 = \u5355\u4e00\u6700\u4f73 OPRO \u6307\u4ee4\u6587\u672c\u3010\u5916\u90e8\u5148\u9a8c\u00b7\u672a\u9a8c\u8bc1\uff1b\u6587\u672c\u4e0e\u6392\u540d\u5b9a\u7a3f\u524d\u9700\u6743\u5a01\u6587\u732e\u6284\u5f55\uff0c\u6eaf\u6e90\u5b57\u6bb5\"\u672a\u5728\u672c\u4ed3\u5e93\u4e2d\u9a8c\u8bc1\"\u3011\n- C1b/C1c = \u8be5\u6587\u732e\u62a5\u544a\u7684\u524d 3 \u540d\u4e2d\u7684\u7b2c 2\u30013 \u540d\uff08\u4ec5\u654f\u611f\u6027\u81c2\uff09\u3010\u5916\u90e8\u5148\u9a8c\u00b7\u672a\u9a8c\u8bc1\u3011\n- C2 = \"Let's think step by step.\"\u3010\u4ed3\u5e93\u5b9e\u6d4b\uff1atask.json \u6587\u672c\u3011\n- C3 = \u7a7a\u63d0\u793a\uff08\u6a21\u677f\u4fdd\u7559\u3001\u6307\u4ee4\u4f4d\u7f6e\u4e3a\u7a7a\uff0c\u542b\u5171\u7528\u683c\u5f0f\u53e5\uff09\u3010\u4ed3\u5e93\u5b9e\u6d4b\uff08\u6982\u5ff5\uff09+ \u59d4\u6258\u65b9\u88c1\u5b9a\u4e09.2\u3011\n- C3' = \u5b57\u9762\u7a7a\u63d0\u793a\uff08\u4e0d\u9644\u52a0\u683c\u5f0f\u53e5\uff09\u3010\u59d4\u6258\u65b9\u88c1\u5b9a\u4e09.2\uff0c\u654f\u611f\u6027\u81c2\u3011\n- C4 = \u957f\u5ea6\u914d\u5e73\u63a7\u5236\u53e5\uff08\u4e0e C1 \u6307\u4ee4 token \u957f\u5ea6\u8fd1\u4f3c\u76f8\u7b49\u7684\u4e2d\u6027\u6587\u672c\uff09\u3010\u63a2\u7d22\u6027\u3011\n- \u683c\u5f0f\u53e5 = \u4e09\u4e3b\u6761\u4ef6\u5171\u7528\u7684\u5b8c\u5168\u76f8\u540c\u7684\u7b54\u6848\u683c\u5f0f\u7ea6\u675f\u53e5\u3010\u59d4\u6258\u65b9\u88c1\u5b9a\u4e09.2\u3011\n- \u793a\u4f8b = k=3 few-shot\uff0c\u6765\u6e90\u4e3a BBH \u5b98\u65b9\u63d0\u793a\u6587\u4ef6\u4e2d\u7684\u793a\u4f8b\u3010\u5916\u90e8\u5148\u9a8c\u00b7\u672a\u9a8c\u8bc1\uff1bk \u4e0e\u6765\u6e90\u4e3a\u5f85\u6838\u5b57\u6bb5\u3011\n\n| \u5c42 | \u81c2 | \u6761\u4ef6 | k | \u6e29\u5ea6 | \u91cd\u590d | \u8bf4\u660e |\n|---|---|---|---|---|---|---|\n| \u4e3b | P0 | C1,C2,C3 | 3 | 0 | 1 | \u552f\